"""Every container backend fixture, loaded from a descriptor generated by the
real tdd system / domain create (--descriptor-only: nothing provisioned)."""

from __future__ import annotations

import pytest

from tabsdatax.itest.fixture import backend as common
from tabsdatax.itest.fixture.backends.clickhouse import (
    ClickhouseDomain,
    ClickhouseSystem,
)
from tabsdatax.itest.fixture.backends.db2 import Db2Domain, Db2System
from tabsdatax.itest.fixture.backends.mongodb import MongoDBDomain, MongoDBSystem
from tabsdatax.itest.fixture.backends.mssqlserver import (
    MssqlserverDomain,
    MssqlserverSystem,
)
from tabsdatax.itest.fixture.backends.mysql import (
    MysqlDomain,
    MysqlSystem,
    mysql_domain,
    mysql_system,
)
from tabsdatax.itest.fixture.backends.oracle import OracleDomain, OracleSystem
from tabsdatax.itest.fixture.backends.postgres import PostgresDomain, PostgresSystem
from tabsdatax.itest.fixture.backends.redpanda import RedpandaDomain, RedpandaSystem
from tabsdatax.itest.fixture.backends.starrocks import StarrocksDomain, StarrocksSystem

# slug, system_kind, SystemCls, DomainCls
CONTAINER = [
    ("mysql", "sql", MysqlSystem, MysqlDomain),
    ("postgres", "sql", PostgresSystem, PostgresDomain),
    ("mssqlserver", "sql", MssqlserverSystem, MssqlserverDomain),
    ("oracle", "sql", OracleSystem, OracleDomain),
    ("db2", "sql", Db2System, Db2Domain),
    ("mongodb", "mongodb", MongoDBSystem, MongoDBDomain),
    ("redpanda", "kafka", RedpandaSystem, RedpandaDomain),
    ("clickhouse", "sql", ClickhouseSystem, ClickhouseDomain),
    ("starrocks", "sql", StarrocksSystem, StarrocksDomain),
]
IDS = [c[0] for c in CONTAINER]

# The postgres family names the network it is reached on; tests reach it from
# the host, so its host / database / URIs are the external ones.
HOST = {"postgres": "external_host"}
DATABASE = {"postgres": "database"}
SQL_URI = {"postgres": "external_sqlalchemy_uri"}

# The domain attribute that must reference the created entity. Most container
# backends are SQL and carry a SQL URI; the two that are not carry no SQL URI at
# all (mongodb ships a mongodb:// uri of its own, and a redpanda domain *is* a
# topic).
ENTITY_REF = {"mongodb": "uri", "redpanda": "topic"}


@pytest.mark.parametrize("slug,kind,Sys,Dom", CONTAINER, ids=IDS)
def test_container_system(provision, slug, kind, Sys, Dom):
    provision.system(slug, "s")
    obj = common.load("s", Sys)
    assert isinstance(obj, Sys) and obj.system_type == slug
    assert (
        obj.system_kind == kind and getattr(obj, HOST.get(slug, "host")) == "127.0.0.1"
    )
    assert obj.docker_container_name == "tdd_s" and obj.image


@pytest.mark.parametrize("slug,kind,Sys,Dom", CONTAINER, ids=IDS)
def test_container_domain(provision, slug, kind, Sys, Dom):
    provision.system(slug, "s")
    provision.domain("s", "d")
    obj = common.load("d", Dom)
    assert isinstance(obj, Dom) and obj.system_type == slug
    assert (
        obj.system_kind == kind and getattr(obj, HOST.get(slug, "host")) == "127.0.0.1"
    )
    # The entity (database) is the prefixed external name tdd chose,
    # compared case-insensitively since some backends upper-case identifiers
    # (db2); the descriptor's logical name stays "d". The domain's connection
    # handle references that same entity.
    ext = provision.external_name("d")
    assert getattr(obj, DATABASE.get(slug, "db")).lower() == ext.lower()
    sql_uri = SQL_URI.get(slug, "sqlalchemy_uri")
    ref = ENTITY_REF.get(slug, sql_uri)
    assert ext.lower() in getattr(obj, ref).lower()
    if ref != sql_uri:
        assert obj.sqlalchemy_uri is None  # a non-SQL backend carries no SQL URI
    assert obj.model is None and obj.data is None


@pytest.fixture
def mysql_ready(provision):
    provision.system("mysql", "db")
    provision.domain("db", "shop")


@mysql_system("db")
@mysql_domain("shop")
def test_container_injection(
    mysql_ready, system_db: MysqlSystem, domain_shop: MysqlDomain
):
    assert isinstance(system_db, MysqlSystem)
    assert isinstance(domain_shop, MysqlDomain)
    assert system_db.name == "db" and domain_shop.name == "shop"
